"use client"

import { type MutableRefObject, useEffect, useRef } from "react"

export const isEnvBrowser = (): boolean => !(window as any).invokeNative

interface NuiMessageData<T = unknown> {
  action: string
  data: T
}

type NuiHandlerSignature<T> = (data: T) => void

export const useNuiEvent = <T = any>(action: string, handler: (data: T) => void) => {
  const savedHandler: MutableRefObject<NuiHandlerSignature<T>> = useRef(() => {})

  useEffect(() => {
    savedHandler.current = handler
  }, [handler])

  useEffect(() => {
    const eventListener = (event: MessageEvent) => {
      const { action: eventAction, data } = event.data
      if (eventAction && eventAction === action && savedHandler.current) {
        try {
          savedHandler.current(data)
        } catch (error) {
          console.error(`Error in useNuiEvent handler for action ${action}:`, error)
        }
      }
    }

    window.addEventListener("message", eventListener)

    return () => {
      window.removeEventListener("message", eventListener)
    }
  }, [action])
}

export async function fetchNui<T = any>(resourceName: string, eventName: string, data?: any): Promise<T> {
  const options = {
    method: "POST",
    headers: {
      "Content-Type": "application/json; charset=UTF-8",
    },
    body: JSON.stringify(data || {}), // Ensure data is never null
  };

  if (isEnvBrowser()) {
    return Promise.resolve({ success: true, bills: [] } as any); // Simulate a response in development
  }

  try {
    const url = `https://${resourceName}/${eventName}`;
    const resp = await fetch(url, options);

    if (!resp.ok) {
      console.error(`NUI request failed with status: ${resp.status} ${resp.statusText}`); // Log HTTP errors
      return undefined as any;
    }

    const respFormatted = await resp.json();
    return respFormatted;
  } catch (error) {
    console.error(`Error in fetchNui for ${resourceName}/${eventName}:`, error); // Log fetch errors
    return undefined as any;
  }
}
