"use client"

import { useState } from "react"
import { Box, Tabs, LoadingOverlay } from "@mantine/core"
import { useRecoilValue } from "recoil"
import { BillsState, LoadingState } from "../reducers/atoms"
import classes from "./appStyle.module.css"
import { BillsDashboard } from "./BillsDashboard"
import { FilterPanel } from "./FilterPanel"

export const MainApp = () => {
  const [activeTab, setActiveTab] = useState<string | null>("dashboard")
  const loading = useRecoilValue(LoadingState)

  return (
    <Box className={classes.app} pos="relative">
      <LoadingOverlay visible={loading} zIndex={1000} loaderProps={{ color: "teal", type: "dots" }} />

      <Tabs value={activeTab} onChange={setActiveTab} className={classes.tabs}>
        <Tabs.List>
          <Tabs.Tab value="dashboard">Dashboard</Tabs.Tab>
        </Tabs.List>

        <Tabs.Panel value="dashboard">
          <Box className={classes.dashboardContainer}>
            <FilterPanel />
            <BillsDashboard
              onMarkAsPaid={(billId) => {
              }}
            />
          </Box>
        </Tabs.Panel>
      </Tabs>
    </Box>
  )
}
