"use client"

import { useEffect, useState } from "react"
import { Box, Table, Text, Group, ScrollArea, Button } from "@mantine/core"
import { useRecoilState, useSetRecoilState, useRecoilValue } from "recoil"
import { BillsState, LoadingState, FilterState } from "../reducers/atoms"
import { fetchNui } from "../hooks/useNuiEvents"
import type { Bill } from "../types/types"
import { ArrowUp, ArrowDown } from "lucide-react"
import classes from "./appStyle.module.css"

interface BillsDashboardProps {
  onMarkAsPaid: (billId: number) => void
}

// Type guard to validate a single Bill object
const isBill = (obj: any): obj is Bill => {
  return (
    typeof obj === "object" &&
    obj !== null &&
    typeof obj.id === "number" &&
    typeof obj.identifier === "string" &&
    typeof obj.sender === "string" &&
    typeof obj.label === "string" &&
    typeof obj.amount === "number" &&
    typeof obj.time === "number"
  )
}

export const BillsDashboard = ({ onMarkAsPaid }: BillsDashboardProps) => {
  const [bills, setBills] = useRecoilState(BillsState)
  const setLoading = useSetRecoilState(LoadingState)
  const filters = useRecoilValue(FilterState) // Get the current filters
  const [sortOrder, setSortOrder] = useState<"asc" | "desc">("asc") // State for sorting order

  useEffect(() => {
    const fetchBills = async () => {
      setLoading(true)
      try {
        const response = await fetchNui<Bill[]>("fh_billings", "getBills", {})

        if (Array.isArray(response)) {
          setBills(response) // Update the state with the bills array
        } else {
          console.warn("No bills returned or invalid response format.")
          setBills([]) // Clear the state if no valid bills are returned
        }
      } catch (error) {
        console.error("Error in fetchNui for fh_billings/getBills:", error)
        setBills([]) // Clear the state in case of an error
      } finally {
        setLoading(false)
      }
    }

    fetchBills()
  }, [])

  const filteredBills = bills.filter((bill) =>
    bill.identifier.toLowerCase().includes(filters.clientName.toLowerCase()) ||
    bill.sender.toLowerCase().includes(filters.clientName.toLowerCase()) ||
    bill.label.toLowerCase().includes(filters.clientName.toLowerCase())
  )

  const sortedBills = [...filteredBills].sort((a, b) => {
    if (sortOrder === "asc") {
      return b.time - a.time // Ascending order
    } else {
      return a.time - b.time // Descending order
    }
  })

  const toggleSortOrder = () => {
    setSortOrder((prevOrder) => (prevOrder === "asc" ? "desc" : "asc"))
  }

  const handleRemoveBill = async (bill: Bill) => {
    try {
      setLoading(true)
      const response = await fetchNui("fh_billings", "removeBill", { billId: bill.id, billData: bill })
      if (response.success) {
        setBills((prevBills) => prevBills.filter((b) => b.id !== bill.id))
      }
    } catch (error) {
      console.error("Error removing bill:", error)
    } finally {
      setLoading(false)
    }
  }

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("da-DK", {
      style: "currency",
      currency: "DKK",
    }).format(amount)
  }

  const formatDate = (timestamp: number) => {
    return new Date(timestamp * 1000).toLocaleDateString() // Convert UNIX timestamp to date
  }

  return (
    <Box className={classes.billsTable}>
      <Text size="xl" fw={700} mb="md">
        Ubetalte Regninger
      </Text>

      <ScrollArea h={500}>
        <Table striped highlightOnHover>
          <Table.Thead>
            <Table.Tr>
              <Table.Th>Kunde</Table.Th>
              <Table.Th>Medarbejder</Table.Th>
              <Table.Th>Note</Table.Th>
              <Table.Th>Beløb</Table.Th>
              <Table.Th
                onClick={toggleSortOrder}
                style={{ cursor: "pointer", display: "flex", alignItems: "center", gap: "0.5rem" }}
              >
                Dato
                {sortOrder === "asc" ? <ArrowUp size={16} /> : <ArrowDown size={16} />}
              </Table.Th>
              <Table.Th>Handlinger</Table.Th>
            </Table.Tr>
          </Table.Thead>
          <Table.Tbody>
            {sortedBills.length === 0 ? (
              <Table.Tr>
                <Table.Td colSpan={7}>
                  <Text ta="center" fz="sm" c="dimmed">
                    Ingen regninger fundet
                  </Text>
                </Table.Td>
              </Table.Tr>
            ) : (
              sortedBills.map((bill) => (
                <Table.Tr key={bill.id}>
                  <Table.Td>{bill.identifier || "N/A"}</Table.Td>
                  <Table.Td>{bill.sender || "N/A"}</Table.Td>
                  <Table.Td>{bill.label || "N/A"}</Table.Td>
                  <Table.Td>{formatCurrency(bill.amount || 0)}</Table.Td>
                  <Table.Td>{bill.time ? formatDate(bill.time) : "N/A"}</Table.Td>
                  <Table.Td>
                    <Group gap="xs">
                      <Button
                        variant="subtle"
                        color="red"
                        onClick={() => handleRemoveBill(bill)}
                      >
                        Fjern
                      </Button>
                    </Group>
                  </Table.Td>
                </Table.Tr>
              ))
            )}
          </Table.Tbody>
        </Table>
      </ScrollArea>
    </Box>
  )
}
