"use client"

import { useEffect, useState } from "react";
import { Box } from "@mantine/core"; // Removed MantineProvider
import { isEnvBrowser } from "./hooks/useNuiEvents";
import { Lang, BillsState, LoadingState } from "./reducers/atoms";
import { useRecoilState, useSetRecoilState } from "recoil";
import { MainApp } from "./components/MainApp";
import { Loading } from "./components/Loading";
import { getLang } from "./hooks/getLang";
import { useNuiEvent } from "./hooks/useNuiEvents";
import type { Bill } from "./types/types";
import "./App.css";
import "@mantine/core/styles.css";
import "@mantine/dates/styles.css";

const App = () => {
  const setLang = useSetRecoilState(Lang);
  const [bills, setBills] = useRecoilState(BillsState);
  const setLoading = useSetRecoilState(LoadingState);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    const fetchLang = async () => {
      const resp = await getLang();
      setLang(resp);
      setLoaded(true);
    };
    fetchLang();
  }, []);

  // Listen for bill updates from the server
  useNuiEvent<{ bills: Bill[] }>("updateBills", (data) => {
    if (data && data.bills) {
      setBills(data.bills);
    }
  });

  // Listen for bill status changes
  useNuiEvent<{ billId: number; status: "paid" | "unpaid" | "overdue" }>("updateBillStatus", (data) => {
    if (data && data.billId) {
      setBills((prevBills) =>
        prevBills.map((bill) => (bill.id === data.billId ? { ...bill, status: data.status } : bill))
      );
    }
  });

  return (
    <>
      {loaded ? (
        isEnvBrowser() ? (
          <>
            <Box
              className="main-container"
              style={{
                backgroundColor: isEnvBrowser() ? "black" : "transparent",
              }}
            >
              <Box
                className="laptop-frame"
                style={{
                  backgroundImage: `url(https://raw.githubusercontent.com/Renovamen/playground-macos/main/public/img/ui/wallpaper-night.jpg)`,
                  backgroundSize: "cover",
                }}
              >
                <Box className="app-window">
                  <Box className="app-bar"></Box>
                  <MainApp />
                </Box>
              </Box>
            </Box>
          </>
        ) : (
          <MainApp />
        )
      ) : (
        <Loading />
      )}
    </>
  );
};
export default App;
