"use client"

import { useState } from "react"
import { Box, TextInput, Button, Accordion, Text } from "@mantine/core"
import { useRecoilState } from "recoil"
import { FilterState } from "../reducers/atoms"
import { FilterX, Search } from "lucide-react"
import classes from "./appStyle.module.css"

export const FilterPanel = () => {
  const [filters, setFilters] = useRecoilState(FilterState)
  const [localFilters, setLocalFilters] = useState(filters)

  const handleApplyFilters = () => {
    setFilters(localFilters)
  }

  const handleResetFilters = () => {
    const resetFilters = {
      clientName: "",
      status: "",
      dateRange: [null, null] as [Date | null, Date | null],
      minAmount: null,
      maxAmount: null,
    }
    setLocalFilters(resetFilters)
    setFilters(resetFilters)
  }

  const handleChange = (field: string, value: any) => {
    setLocalFilters((prev) => ({
      ...prev,
      [field]: value,
    }))
  }

  return (
    <Accordion defaultValue={null} className={classes.filterPanel}>
      <Accordion.Item value="filters">
        <Accordion.Control>
          <Text fw={600}>Søgefunktion</Text>
        </Accordion.Control>
        <Accordion.Panel>
          <Box className={classes.filterForm}>
            <TextInput
              label="Søg efter en medarbejder, kunde eller note"
              placeholder="Palle Larsen"
              value={localFilters.clientName}
              onChange={(e) => {
                const value = e.target.value
                const isValid = /^[a-zA-Z0-9\s]*$/.test(value) // Allow letters, numbers, and spaces
                if (isValid) {
                  handleChange("clientName", value)
                }
              }}
            />
            <Box mt="lg" style={{ display: "flex", justifyContent: "flex-end", gap: "1rem" }}>
              <Button variant="subtle" leftSection={<FilterX size={16} />} onClick={handleResetFilters}>
                Nulstil
              </Button>
              <Button leftSection={<Search size={16} />} onClick={handleApplyFilters}>
                Anvend filtre
              </Button>
            </Box>
          </Box>
        </Accordion.Panel>
      </Accordion.Item>
    </Accordion>
  )
}
